import { Array, pipe } from "effect"

export interface WarehouseBalance {
  readonly warehouseId: string
  readonly productId: string
  readonly available: number
  readonly reserved: number
  readonly active: boolean
}

export const buildAvailabilityIndex = (
  balances: ReadonlyArray<WarehouseBalance>,
  warehouseId: string
): Map<string, number> => {
  const availability = pipe(
    balances,
    Array.filter((balance) => balance.active && balance.warehouseId === warehouseId),
    Array.map((balance) => [
      balance.productId,
      Math.max(0, balance.available - balance.reserved)
    ] as const),
    (entries) => new Map(entries)
  )

  return availability
}

export const getAvailableQuantity = (
  availability: ReadonlyMap<string, number>,
  productId: string
): number => availability.get(productId) ?? 0
